#!/usr/bin/env node
/**
 * slack_api.cjs - dependency-free Slack Web API client for LLM agents.
 *
 * Usage:
 *   node slack_api.cjs <api.method> [--param value]...
 *
 * Auth:
 *   export SLACK_TOKEN=xoxb-...   (falls back to SLACK_BOT_TOKEN)
 *
 * Output:
 *   Prints Slack's JSON response to stdout and exits 0 when ok:true.
 *   Prints "Failure: <reason>" to stderr and exits 1 otherwise.
 *   Never logs the token.
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const API_BASE = 'https://slack.com/api';
const DEFAULT_MAX_OUTPUT = 20000;
const MAX_PAGES = 50;

const USAGE = `Slack Web API helper
Usage:
  node slack_api.cjs <api.method> [--param value]...

Examples:
  node slack_api.cjs chat.postMessage --channel C123456 --text "Hello :wave:"
  node slack_api.cjs conversations.list --types public_channel,private_channel --paginate
  node slack_api.cjs conversations.history --channel C123456 --limit 100
  node slack_api.cjs users.lookupByEmail --email ada@example.com
  node slack_api.cjs files.upload --channels C123456 --file ./report.pdf --title "Report"

Auth:    export SLACK_TOKEN=xoxb-...   (falls back to SLACK_BOT_TOKEN)
Flags:   --file PATH       attach a local file (multipart upload)
         --paginate        follow next_cursor and merge array results (max ${MAX_PAGES} pages)
         --max-output N    cap printed JSON length in chars (default ${DEFAULT_MAX_OUTPUT})
         --raw             print the full JSON response
         --self-test       run offline diagnostics (no network, no token needed)
Output:  Slack JSON on stdout; exit code 0 on ok:true, 1 otherwise.
         Errors and truncation notes go to stderr. The token is never echoed.`;

function cap(text, max) {
  if (text.length <= max) return { text, truncated: false };
  return { text: text.slice(0, max), truncated: true };
}

function parseArgs(argv) {
  const options = {
    flags: {},
    file: null,
    paginate: false,
    raw: false,
    maxOutput: DEFAULT_MAX_OUTPUT,
    selfTest: false,
    method: null,
  };
  const positionals = [];
  let i = 0;
  const takeValue = (name) => {
    const v = argv[i + 1];
    if (v === undefined || (v.startsWith('--') && v.length > 2)) {
      throw new Error(
        `Flag --${name} requires a value (use --${name}=value for values that start with '-')`,
      );
    }
    i += 1;
    return v;
  };
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '--self-test') {
      options.selfTest = true;
    } else if (arg === '--paginate') {
      options.paginate = true;
    } else if (arg === '--raw') {
      options.raw = true;
    } else if (arg === '--file') {
      options.file = takeValue('file');
    } else if (arg === '--max-output') {
      const rawValue = takeValue('max-output');
      const n = Number(rawValue);
      if (!Number.isFinite(n) || n <= 0) {
        throw new Error('--max-output must be a positive integer');
      }
      options.maxOutput = Math.floor(n);
    } else if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        options.flags[arg.slice(2, eq)] = arg.slice(eq + 1);
      } else {
        options.flags[arg.slice(2)] = takeValue(arg.slice(2));
      }
    } else {
      positionals.push(arg);
    }
    i += 1;
  }
  if (positionals.length > 1) {
    throw new Error(`Unexpected extra arguments: ${positionals.slice(1).join(' ')}`);
  }
  options.method = positionals[0] || null;
  return options;
}

function mimeFor(ext) {
  const map = {
    '.pdf': 'application/pdf',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.webp': 'image/webp',
    '.txt': 'text/plain',
    '.md': 'text/plain',
    '.csv': 'text/csv',
    '.json': 'application/json',
    '.zip': 'application/zip',
    '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  };
  return map[String(ext).toLowerCase()] || 'application/octet-stream';
}

async function sendRequest(method, flags, opts) {
  const fetchFn = opts.fetchImpl || globalThis.fetch;
  if (typeof fetchFn !== 'function') {
    throw new Error('fetch is not available; run this script with Node.js >= 18');
  }
  const url = `${API_BASE}/${method}`;
  const headers = { Authorization: `Bearer ${opts.token}` };
  let body;
  if (opts.filePath) {
    if (typeof FormData === 'undefined' || typeof Blob === 'undefined') {
      throw new Error('--file requires Node.js >= 18 (FormData/Blob)');
    }
    const buffer = fs.readFileSync(opts.filePath);
    const form = new FormData();
    for (const [key, value] of Object.entries(flags)) form.append(key, String(value));
    form.append(
      'file',
      new Blob([buffer], { type: mimeFor(path.extname(opts.filePath)) }),
      path.basename(opts.filePath),
    );
    body = form;
  } else {
    const form = new URLSearchParams();
    for (const [key, value] of Object.entries(flags)) form.append(key, String(value));
    body = form;
  }
  let res;
  try {
    res = await fetchFn(url, { method: 'POST', headers, body });
  } catch (err) {
    throw new Error(`network request failed: ${err.message}`);
  }
  const retryAfter =
    res.headers && typeof res.headers.get === 'function'
      ? res.headers.get('retry-after')
      : null;
  const raw = await res.text();
  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    const short = cap(raw.replace(/\s+/g, ' ').trim(), 300);
    throw new Error(
      `Slack returned non-JSON (HTTP ${res.status}): ${short.text}${short.truncated ? '...' : ''}`,
    );
  }
  if (data.ok !== true) {
    const bits = [`Slack API error: ${data.error || 'unknown'}`];
    if (data.needed) bits.push(`missing scope '${data.needed}' - add it to the app and reinstall`);
    if (retryAfter) bits.push(`rate limited - retry after ${retryAfter}s`);
    throw new Error(bits.join(' | '));
  }
  return data;
}

async function callMethod(method, flags, opts, paginate) {
  if (!paginate) return sendRequest(method, flags, opts);
  const pages = [];
  let pageFlags = flags;
  for (let pageNo = 0; pageNo < MAX_PAGES; pageNo += 1) {
    const data = await sendRequest(method, pageFlags, opts);
    pages.push(data);
    const next = data.response_metadata && data.response_metadata.next_cursor;
    if (!next || next === '') break;
    pageFlags = Object.assign({}, flags, { cursor: next });
  }
  if (pages.length === 1) return pages[0];
  const merged = { ok: true, pagination: { pages: pages.length } };
  for (const page of pages) {
    for (const [key, value] of Object.entries(page)) {
      if (key === 'ok' || key === 'response_metadata') continue;
      if (Array.isArray(value)) {
        if (!Array.isArray(merged[key])) merged[key] = [];
        merged[key].push(...value);
      } else if (key === 'has_more') {
        merged.has_more = false;
      } else {
        merged[key] = value; // scalar: last page wins
      }
    }
  }
  return merged;
}

function printJson(data, maxOutput, raw) {
  const full = JSON.stringify(data, null, 2);
  if (raw || full.length <= maxOutput) {
    process.stdout.write(full + '\n');
    return;
  }
  const short = cap(full, maxOutput);
  process.stdout.write(short.text + '\n');
  process.stderr.write(
    `Note: output truncated to ${maxOutput} characters (full response is ${full.length}); rerun with --raw to print everything.\n`,
  );
}

async function runSelfTest() {
  let passed = 0;
  const skipped = [];
  const assert = (cond, name) => {
    if (!cond) throw new Error(`self-test check failed: ${name}`);
    passed += 1;
  };
  try {
    const a = parseArgs([
      'chat.postMessage',
      '--channel',
      'C123',
      '--text=hello world',
      '--paginate',
      '--max-output',
      '500',
    ]);
    assert(a.method === 'chat.postMessage', 'parses positional method');
    assert(a.flags.channel === 'C123' && a.flags.text === 'hello world', 'parses space and = flag forms');
    assert(a.paginate === true && a.maxOutput === 500, 'parses switches and numeric options');

    const t = cap('1234567890', 5);
    assert(t.text === '12345' && t.truncated === true, 'cap() truncates output');

    const calls = [];
    const fakeFetch = async (url, init) => {
      calls.push({ url, init });
      return {
        ok: true,
        status: 200,
        headers: { get: () => null },
        text: async () => JSON.stringify({ ok: true, channel: 'C123', ts: '1712345678.012345' }),
      };
    };

    const data = await sendRequest(
      'chat.postMessage',
      { channel: 'C123', text: 'hi' },
      { token: 'xoxb-test', filePath: null, fetchImpl: fakeFetch },
    );
    assert(data.ok === true && calls.length === 1, 'success path returns parsed JSON');
    assert(calls[0].url === 'https://slack.com/api/chat.postMessage', 'posts to correct endpoint');
    assert(calls[0].init.headers.Authorization === 'Bearer xoxb-test', 'sends bearer auth header');
    const body = calls[0].init.body;
    assert(
      body instanceof URLSearchParams && body.get('channel') === 'C123' && body.get('text') === 'hi',
      'sends form-encoded params',
    );

    if (typeof FormData !== 'undefined' && typeof Blob !== 'undefined') {
      const tmp = path.join(process.cwd(), '.slack_api_selftest_upload.txt');
      fs.writeFileSync(tmp, 'hello file', 'utf8');
      try {
        await sendRequest(
          'files.upload',
          { channels: 'C123' },
          { token: 'xoxb-test', filePath: tmp, fetchImpl: fakeFetch },
        );
        const uploadCall = calls[calls.length - 1];
        const form = uploadCall.init.body;
        assert(
          form instanceof FormData &&
            typeof form.get === 'function' &&
            form.get('channels') === 'C123' &&
            form.getAll('file').length === 1,
          'builds multipart body with file part',
        );
      } finally {
        try {
          fs.unlinkSync(tmp);
        } catch (e) {
          /* ignore cleanup errors */
        }
      }
    } else {
      skipped.push('FormData unavailable (Node < 18)');
    }

    const failFetch = async () => ({
      ok: true,
      status: 200,
      headers: { get: () => null },
      text: async () => JSON.stringify({ ok: false, error: 'invalid_auth' }),
    });
    let threw = null;
    try {
      await sendRequest('auth.test', {}, { token: 'xoxb-bad', filePath: null, fetchImpl: failFetch });
    } catch (err) {
      threw = err;
    }
    assert(threw !== null && /invalid_auth/.test(threw.message), 'surfaces ok:false errors');

    const pages = [
      { ok: true, messages: [{ ts: '1.0', text: 'a' }], has_more: true, response_metadata: { next_cursor: 'c1' } },
      { ok: true, messages: [{ ts: '2.0', text: 'b' }], has_more: false, response_metadata: { next_cursor: '' } },
    ];
    let pageIndex = 0;
    const pageFetch = async () => {
      const page = pages[pageIndex];
      pageIndex += 1;
      return { ok: true, status: 200, headers: { get: () => null }, text: async () => JSON.stringify(page) };
    };
    const merged = await callMethod(
      'conversations.history',
      { channel: 'C123' },
      { token: 'xoxb-test', filePath: null, fetchImpl: pageFetch },
      true,
    );
    assert(
      merged.messages.length === 2 && pageIndex === 2 && merged.ok === true && merged.has_more === false,
      'follows next_cursor and merges arrays',
    );

    const skipNote = skipped.length ? `; skipped ${skipped.length}: ${skipped.join(', ')}` : '';
    process.stdout.write(`Success: self-test passed (${passed} checks${skipNote}).\n`);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exitCode = 1;
  }
}

async function main() {
  let options;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.stderr.write(USAGE + '\n');
    process.exitCode = 1;
    return;
  }
  if (options.selfTest) {
    await runSelfTest();
    return;
  }
  if (!options.method) {
    process.stderr.write('Failure: missing API method (for example: chat.postMessage).\n');
    process.stderr.write(USAGE + '\n');
    process.exitCode = 1;
    return;
  }
  if (!/^[a-z_][a-z0-9_]*\.[a-zA-Z0-9_]+$/.test(options.method)) {
    process.stderr.write(
      `Failure: '${options.method}' is not a valid Slack API method name (expected section.method, e.g. chat.postMessage).\n`,
    );
    process.exitCode = 1;
    return;
  }
  const token = process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
  if (!token) {
    process.stderr.write(
      'Failure: no Slack token found. Export one first, e.g. export SLACK_TOKEN=xoxb-... (or set SLACK_BOT_TOKEN).\n',
    );
    process.exitCode = 1;
    return;
  }
  if (options.file && !fs.existsSync(options.file)) {
    process.stderr.write(`Failure: file not found: ${options.file}\n`);
    process.exitCode = 1;
    return;
  }
  try {
    const opts = { token, filePath: options.file, fetchImpl: null };
    const result = await callMethod(options.method, options.flags, opts, options.paginate);
    printJson(result, options.maxOutput, options.raw);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exitCode = 1;
  }
}

main();

#!/usr/bin/env node
/**
 * Task-local skill packager: validates a skill folder, then writes a .skill
 * zip archive using only Node built-ins (no system 'zip' required).
 *
 * Usage:
 *   node task_package_skill.cjs <skill-folder> [output-dir] [--verify]
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const args = process.argv.slice(2);
const verify = args.includes('--verify');
const positional = args.filter((a) => a !== '--verify');
const skillDirArg = positional[0] || 'slack-api';
const outDirArg = positional[1] || '.';
const skillDir = path.resolve(skillDirArg);
const skillName = path.basename(skillDir);
const outPath = path.join(path.resolve(outDirArg), `${skillName}.skill`);

function fail(msg) {
  process.stderr.write(`Failure: ${msg}\n`);
  process.exit(1);
}

// ---------- validation ----------
if (!fs.existsSync(path.join(skillDir, 'SKILL.md'))) fail(`SKILL.md missing in ${skillDir}`);
const skillMd = fs.readFileSync(path.join(skillDir, 'SKILL.md'), 'utf8');
const fmMatch = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(skillMd);
if (!fmMatch) fail('SKILL.md must start with YAML frontmatter delimited by ---');
const fm = fmMatch[1];
const nameLine = /^name:\s*(.+)$/m.exec(fm);
const descLine = /^description:\s*(.+)$/m.exec(fm);
if (!nameLine || !descLine) fail('frontmatter must contain both name and description');
if (nameLine[1].trim() !== skillName) {
  fail(`frontmatter name '${nameLine[1].trim()}' does not match folder name '${skillName}'`);
}
const desc = descLine[1].trim().replace(/^["']|["']$/g, '');
if (!desc || desc.length < 40) fail('description must be informative (at least 40 characters)');
if (/TODO|TBD|lorem ipsum/i.test(skillMd)) fail('skill still contains TODO/TBD placeholder text');
for (const rel of ['scripts/slack_api.cjs', 'references/api.md']) {
  if (!fs.existsSync(path.join(skillDir, rel))) fail(`required file missing: ${rel}`);
}

// ---------- collect files ----------
function walk(dir, base) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    const rel = path.join(base, entry.name);
    if (entry.isDirectory()) out.push(...walk(abs, rel));
    else out.push(rel);
  }
  return out;
}
const files = walk(skillDir, '.')
  .map((p) => p.split(path.sep).join('/'))
  .filter((f) => !f.startsWith('.'))
  .sort();
if (files.length === 0) fail('skill folder contains no files');

// ---------- zip writing (built-in only) ----------
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i += 1) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
const enc = (s) => Buffer.from(s, 'utf8');
const u16 = (v) => {
  const b = Buffer.alloc(2);
  b.writeUInt16LE(v & 0xffff, 0);
  return b;
};
const u32 = (v) => {
  const b = Buffer.alloc(4);
  b.writeUInt32LE(v >>> 0, 0);
  return b;
};

const chunks = [];
const central = [];
let offset = 0;
for (const rel of files) {
  const data = fs.readFileSync(path.join(skillDir, rel));
  const name = enc(rel);
  const crc = crc32(data);
  const deflated = zlib.deflateRawSync(data, { level: 9 });
  chunks.push(
    u32(0x04034b50), u16(20), u16(0), u16(8), u16(0), u16(0),
    u32(crc), u32(deflated.length), u32(data.length), u16(name.length), u16(0),
    name, deflated,
  );
  central.push({ name, crc, csize: deflated.length, usize: data.length, offset });
  offset += 30 + name.length + deflated.length;
}
const cdStart = offset;
const cdChunks = [];
for (const e of central) {
  cdChunks.push(
    u32(0x02014b50), u16(20), u16(20), u16(0), u16(8), u16(0), u16(0),
    u32(e.crc), u32(e.csize), u32(e.usize),
    u16(e.name.length), u16(0), u16(0), u16(0), u16(0),
    u32(0), u32((0o100644 << 16) >>> 0), u32(e.offset),
    e.name,
  );
}
const cdBuf = Buffer.concat(cdChunks);
const eocd = Buffer.concat([
  u32(0x06054b50), u16(0), u16(0), u16(central.length), u16(central.length),
  u32(cdBuf.length), u32(cdStart), u16(0),
]);
const zip = Buffer.concat([Buffer.concat(chunks), cdBuf, eocd]);
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, zip);
process.stdout.write(
  `Success: validated and packaged ${central.length} file(s) into ${outPath} (${zip.length} bytes).\n`,
);

// ---------- verify by re-parsing the archive ----------
if (verify) {
  const buf = fs.readFileSync(outPath);
  let eocdIdx = -1;
  for (let i = buf.length - 22; i >= 0; i -= 1) {
    if (buf.readUInt32LE(i) === 0x06054b50) {
      eocdIdx = i;
      break;
    }
  }
  if (eocdIdx < 0) fail('end-of-central-directory record not found in archive');
  const count = buf.readUInt16LE(eocdIdx + 10);
  const cdSize = buf.readUInt32LE(eocdIdx + 12);
  const cdOff = buf.readUInt32LE(eocdIdx + 16);
  let pos = cdOff;
  let verified = 0;
  for (let i = 0; i < count; i += 1) {
    if (buf.readUInt32LE(pos) !== 0x02014b50) fail(`bad central directory header at offset ${pos}`);
    const method = buf.readUInt16LE(pos + 10);
    const crcExpected = buf.readUInt32LE(pos + 16);
    const csize = buf.readUInt32LE(pos + 20);
    const usize = buf.readUInt32LE(pos + 24);
    const nameLen = buf.readUInt16LE(pos + 28);
    const extraLen = buf.readUInt16LE(pos + 30);
    const commentLen = buf.readUInt16LE(pos + 32);
    const name = buf.toString('utf8', pos + 46, pos + 46 + nameLen);
    const localOff = buf.readUInt32LE(pos + 42);
    pos += 46 + nameLen + extraLen + commentLen;
    if (buf.readUInt32LE(localOff) !== 0x04034b50) fail(`bad local file header for ${name}`);
    const lNameLen = buf.readUInt16LE(localOff + 26);
    const lExtraLen = buf.readUInt16LE(localOff + 28);
    const dataStart = localOff + 30 + lNameLen + lExtraLen;
    const stored = buf.subarray(dataStart, dataStart + csize);
    const rawData = method === 8 ? zlib.inflateRawSync(stored) : stored;
    if (rawData.length !== usize) fail(`size mismatch for ${name}`);
    if (crc32(rawData) !== crcExpected) fail(`CRC mismatch for ${name}`);
    process.stdout.write(`Verified: ${name}\n`);
    verified += 1;
  }
  if (verified !== count || cdSize !== cdBuf.length) {
    fail(`expected ${count} entries with ${cdBuf.length} bytes of central directory`);
  }
  process.stdout.write(`Success: archive integrity verified (${verified} entries).\n`);
}

#!/usr/bin/env node
/**
 * slack_api.cjs - dependency-free Slack Web API client for LLM agents.
 *
 * Usage:
 *   node slack_api.cjs <api.method> [--param value]...
 *
 * Auth:
 *   export SLACK_TOKEN=xoxb-...   (falls back to SLACK_BOT_TOKEN)
 *
 * Output:
 *   Prints Slack's JSON response to stdout and exits 0 when ok:true.
 *   Prints "Failure: <reason>" to stderr and exits 1 otherwise.
 *   Never logs the token.
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const API_BASE = 'https://slack.com/api';
const DEFAULT_MAX_OUTPUT = 20000;
const MAX_PAGES = 50;

const USAGE = `Slack Web API helper
Usage:
  node slack_api.cjs <api.method> [--param value]...

Examples:
  node slack_api.cjs chat.postMessage --channel C123456 --text "Hello :wave:"
  node slack_api.cjs conversations.list --types public_channel,private_channel --paginate
  node slack_api.cjs conversations.history --channel C123456 --limit 100
  node slack_api.cjs users.lookupByEmail --email ada@example.com
  node slack_api.cjs files.upload --channels C123456 --file ./report.pdf --title "Report"

Auth:    export SLACK_TOKEN=xoxb-...   (falls back to SLACK_BOT_TOKEN)
Flags:   --file PATH       attach a local file (multipart upload)
         --paginate        follow next_cursor and merge array results (max ${MAX_PAGES} pages)
         --max-output N    cap printed JSON length in chars (default ${DEFAULT_MAX_OUTPUT})
         --raw             print the full JSON response
         --self-test       run offline diagnostics (no network, no token needed)
Output:  Slack JSON on stdout; exit code 0 on ok:true, 1 otherwise.
         Errors and truncation notes go to stderr. The token is never echoed.`;

function cap(text, max) {
  if (text.length <= max) return { text, truncated: false };
  return { text: text.slice(0, max), truncated: true };
}

function parseArgs(argv) {
  const options = {
    flags: {},
    file: null,
    paginate: false,
    raw: false,
    maxOutput: DEFAULT_MAX_OUTPUT,
    selfTest: false,
    method: null,
  };
  const positionals = [];
  let i = 0;
  const takeValue = (name) => {
    const v = argv[i + 1];
    if (v === undefined || (v.startsWith('--') && v.length > 2)) {
      throw new Error(
        `Flag --${name} requires a value (use --${name}=value for values that start with '-')`,
      );
    }
    i += 1;
    return v;
  };
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '--self-test') {
      options.selfTest = true;
    } else if (arg === '--paginate') {
      options.paginate = true;
    } else if (arg === '--raw') {
      options.raw = true;
    } else if (arg === '--file') {
      options.file = takeValue('file');
    } else if (arg === '--max-output') {
      const rawValue = takeValue('max-output');
      const n = Number(rawValue);
      if (!Number.isFinite(n) || n <= 0) {
        throw new Error('--max-output must be a positive integer');
      }
      options.maxOutput = Math.floor(n);
    } else if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        options.flags[arg.slice(2, eq)] = arg.slice(eq + 1);
      } else {
        options.flags[arg.slice(2)] = takeValue(arg.slice(2));
      }
    } else {
      positionals.push(arg);
    }
    i += 1;
  }
  if (positionals.length > 1) {
    throw new Error(`Unexpected extra arguments: ${positionals.slice(1).join(' ')}`);
  }
  options.method = positionals[0] || null;
  return options;
}

function mimeFor(ext) {
  const map = {
    '.pdf': 'application/pdf',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.webp': 'image/webp',
    '.txt': 'text/plain',
    '.md': 'text/plain',
    '.csv': 'text/csv',
    '.json': 'application/json',
    '.zip': 'application/zip',
    '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  };
  return map[String(ext).toLowerCase()] || 'application/octet-stream';
}

async function sendRequest(method, flags, opts) {
  const fetchFn = opts.fetchImpl || globalThis.fetch;
  if (typeof fetchFn !== 'function') {
    throw new Error('fetch is not available; run this script with Node.js >= 18');
  }
  const url = `${API_BASE}/${method}`;
  const headers = { Authorization: `Bearer ${opts.token}` };
  let body;
  if (opts.filePath) {
    if (typeof FormData === 'undefined' || typeof Blob === 'undefined') {
      throw new Error('--file requires Node.js >= 18 (FormData/Blob)');
    }
    const buffer = fs.readFileSync(opts.filePath);
    const form = new FormData();
    for (const [key, value] of Object.entries(flags)) form.append(key, String(value));
    form.append(
      'file',
      new Blob([buffer], { type: mimeFor(path.extname(opts.filePath)) }),
      path.basename(opts.filePath),
    );
    body = form;
  } else {
    const form = new URLSearchParams();
    for (const [key, value] of Object.entries(flags)) form.append(key, String(value));
    body = form;
  }
  let res;
  try {
    res = await fetchFn(url, { method: 'POST', headers, body });
  } catch (err) {
    throw new Error(`network request failed: ${err.message}`);
  }
  const retryAfter =
    res.headers && typeof res.headers.get === 'function'
      ? res.headers.get('retry-after')
      : null;
  const raw = await res.text();
  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    const short = cap(raw.replace(/\s+/g, ' ').trim(), 300);
    throw new Error(
      `Slack returned non-JSON (HTTP ${res.status}): ${short.text}${short.truncated ? '...' : ''}`,
    );
  }
  if (data.ok !== true) {
    const bits = [`Slack API error: ${data.error || 'unknown'}`];
    if (data.needed) bits.push(`missing scope '${data.needed}' - add it to the app and reinstall`);
    if (retryAfter) bits.push(`rate limited - retry after ${retryAfter}s`);
    throw new Error(bits.join(' | '));
  }
  return data;
}

async function callMethod(method, flags, opts, paginate) {
  if (!paginate) return sendRequest(method, flags, opts);
  const pages = [];
  let pageFlags = flags;
  for (let pageNo = 0; pageNo < MAX_PAGES; pageNo += 1) {
    const data = await sendRequest(method, pageFlags, opts);
    pages.push(data);
    const next = data.response_metadata && data.response_metadata.next_cursor;
    if (!next || next === '') break;
    pageFlags = Object.assign({}, flags, { cursor: next });
  }
  if (pages.length === 1) return pages[0];
  const merged = { ok: true, pagination: { pages: pages.length } };
  for (const page of pages) {
    for (const [key, value] of Object.entries(page)) {
      if (key === 'ok' || key === 'response_metadata') continue;
      if (Array.isArray(value)) {
        if (!Array.isArray(merged[key])) merged[key] = [];
        merged[key].push(...value);
      } else if (key === 'has_more') {
        merged.has_more = false;
      } else {
        merged[key] = value; // scalar: last page wins
      }
    }
  }
  return merged;
}

function printJson(data, maxOutput, raw) {
  const full = JSON.stringify(data, null, 2);
  if (raw || full.length <= maxOutput) {
    process.stdout.write(full + '\n');
    return;
  }
  const short = cap(full, maxOutput);
  process.stdout.write(short.text + '\n');
  process.stderr.write(
    `Note: output truncated to ${maxOutput} characters (full response is ${full.length}); rerun with --raw to print everything.\n`,
  );
}

async function runSelfTest() {
  let passed = 0;
  const skipped = [];
  const assert = (cond, name) => {
    if (!cond) throw new Error(`self-test check failed: ${name}`);
    passed += 1;
  };
  try {
    const a = parseArgs([
      'chat.postMessage',
      '--channel',
      'C123',
      '--text=hello world',
      '--paginate',
      '--max-output',
      '500',
    ]);
    assert(a.method === 'chat.postMessage', 'parses positional method');
    assert(a.flags.channel === 'C123' && a.flags.text === 'hello world', 'parses space and = flag forms');
    assert(a.paginate === true && a.maxOutput === 500, 'parses switches and numeric options');

    const t = cap('1234567890', 5);
    assert(t.text === '12345' && t.truncated === true, 'cap() truncates output');

    const calls = [];
    const fakeFetch = async (url, init) => {
      calls.push({ url, init });
      return {
        ok: true,
        status: 200,
        headers: { get: () => null },
        text: async () => JSON.stringify({ ok: true, channel: 'C123', ts: '1712345678.012345' }),
      };
    };

    const data = await sendRequest(
      'chat.postMessage',
      { channel: 'C123', text: 'hi' },
      { token: 'xoxb-test', filePath: null, fetchImpl: fakeFetch },
    );
    assert(data.ok === true && calls.length === 1, 'success path returns parsed JSON');
    assert(calls[0].url === 'https://slack.com/api/chat.postMessage', 'posts to correct endpoint');
    assert(calls[0].init.headers.Authorization === 'Bearer xoxb-test', 'sends bearer auth header');
    const body = calls[0].init.body;
    assert(
      body instanceof URLSearchParams && body.get('channel') === 'C123' && body.get('text') === 'hi',
      'sends form-encoded params',
    );

    if (typeof FormData !== 'undefined' && typeof Blob !== 'undefined') {
      const tmp = path.join(process.cwd(), '.slack_api_selftest_upload.txt');
      fs.writeFileSync(tmp, 'hello file', 'utf8');
      try {
        await sendRequest(
          'files.upload',
          { channels: 'C123' },
          { token: 'xoxb-test', filePath: tmp, fetchImpl: fakeFetch },
        );
        const uploadCall = calls[calls.length - 1];
        const form = uploadCall.init.body;
        assert(
          form instanceof FormData &&
            typeof form.get === 'function' &&
            form.get('channels') === 'C123' &&
            form.getAll('file').length === 1,
          'builds multipart body with file part',
        );
      } finally {
        try {
          fs.unlinkSync(tmp);
        } catch (e) {
          /* ignore cleanup errors */
        }
      }
    } else {
      skipped.push('FormData unavailable (Node < 18)');
    }

    const failFetch = async () => ({
      ok: true,
      status: 200,
      headers: { get: () => null },
      text: async () => JSON.stringify({ ok: false, error: 'invalid_auth' }),
    });
    let threw = null;
    try {
      await sendRequest('auth.test', {}, { token: 'xoxb-bad', filePath: null, fetchImpl: failFetch });
    } catch (err) {
      threw = err;
    }
    assert(threw !== null && /invalid_auth/.test(threw.message), 'surfaces ok:false errors');

    const pages = [
      { ok: true, messages: [{ ts: '1.0', text: 'a' }], has_more: true, response_metadata: { next_cursor: 'c1' } },
      { ok: true, messages: [{ ts: '2.0', text: 'b' }], has_more: false, response_metadata: { next_cursor: '' } },
    ];
    let pageIndex = 0;
    const pageFetch = async () => {
      const page = pages[pageIndex];
      pageIndex += 1;
      return { ok: true, status: 200, headers: { get: () => null }, text: async () => JSON.stringify(page) };
    };
    const merged = await callMethod(
      'conversations.history',
      { channel: 'C123' },
      { token: 'xoxb-test', filePath: null, fetchImpl: pageFetch },
      true,
    );
    assert(
      merged.messages.length === 2 && pageIndex === 2 && merged.ok === true && merged.has_more === false,
      'follows next_cursor and merges arrays',
    );

    const skipNote = skipped.length ? `; skipped ${skipped.length}: ${skipped.join(', ')}` : '';
    process.stdout.write(`Success: self-test passed (${passed} checks${skipNote}).\n`);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exitCode = 1;
  }
}

async function main() {
  let options;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.stderr.write(USAGE + '\n');
    process.exitCode = 1;
    return;
  }
  if (options.selfTest) {
    await runSelfTest();
    return;
  }
  if (!options.method) {
    process.stderr.write('Failure: missing API method (for example: chat.postMessage).\n');
    process.stderr.write(USAGE + '\n');
    process.exitCode = 1;
    return;
  }
  if (!/^[a-z_][a-z0-9_]*\.[a-zA-Z0-9_]+$/.test(options.method)) {
    process.stderr.write(
      `Failure: '${options.method}' is not a valid Slack API method name (expected section.method, e.g. chat.postMessage).\n`,
    );
    process.exitCode = 1;
    return;
  }
  const token = process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
  if (!token) {
    process.stderr.write(
      'Failure: no Slack token found. Export one first, e.g. export SLACK_TOKEN=xoxb-... (or set SLACK_BOT_TOKEN).\n',
    );
    process.exitCode = 1;
    return;
  }
  if (options.file && !fs.existsSync(options.file)) {
    process.stderr.write(`Failure: file not found: ${options.file}\n`);
    process.exitCode = 1;
    return;
  }
  try {
    const opts = { token, filePath: options.file, fetchImpl: null };
    const result = await callMethod(options.method, options.flags, opts, options.paginate);
    printJson(result, options.maxOutput, options.raw);
  } catch (err) {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exitCode = 1;
  }
}

main();
